ALTER TABLE documents ADD COLUMN owner_user_id uuid, ADD COLUMN type text NOT NULL DEFAULT 'other', ADD COLUMN metadata_cipher text, ADD COLUMN bytes integer CHECK(bytes BETWEEN 1 AND 5242880), ADD COLUMN envelope_key_cipher text, ADD COLUMN scan_details_cipher text, ADD COLUMN scanned_at timestamptz, ADD COLUMN deleted_at timestamptz, ADD COLUMN retained boolean NOT NULL DEFAULT false;
UPDATE documents d SET owner_user_id=p.owner_user_id FROM prep_dossiers p WHERE p.id=d.dossier_id AND p.organization_id=d.organization_id;
ALTER TABLE documents ALTER COLUMN owner_user_id SET NOT NULL;
ALTER TABLE documents ADD FOREIGN KEY(organization_id,owner_user_id) REFERENCES users(organization_id,id), ADD CHECK(type IN('identity','housing','income','subject','attested-form','other'));
CREATE TABLE form_field_mappings(
 id uuid PRIMARY KEY, organization_id uuid NOT NULL, project_id uuid NOT NULL, release_id uuid NOT NULL REFERENCES project_form_releases(id), form_id text NOT NULL, source_hash text NOT NULL, payload jsonb NOT NULL, content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'), version integer NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','revoked')), approved_by text, approved_at timestamptz, effective_from date NOT NULL, effective_to date, CHECK(effective_to IS NULL OR effective_to>=effective_from), CHECK((status='draft' AND approved_by IS NULL) OR(status IN('approved','revoked') AND approved_by IS NOT NULL AND approved_by<>created_by AND approved_at IS NOT NULL)), FOREIGN KEY(organization_id,project_id) REFERENCES projects(organization_id,id), UNIQUE(organization_id,release_id,version));
CREATE TRIGGER immutable_field_mapping BEFORE UPDATE OR DELETE ON form_field_mappings FOR EACH ROW EXECUTE FUNCTION identity_private.protect_form_release();
CREATE TABLE document_extractions(
 id uuid PRIMARY KEY, organization_id uuid NOT NULL, dossier_id uuid NOT NULL, owner_user_id uuid NOT NULL, document_id uuid NOT NULL REFERENCES documents(id), source_hash text NOT NULL, input_version integer NOT NULL, payload_cipher text NOT NULL, model text NOT NULL, prompt_version text NOT NULL DEFAULT 'document-extraction-v1', accepted_cipher text, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(dossier_id) REFERENCES prep_dossiers(id), FOREIGN KEY(organization_id,owner_user_id) REFERENCES users(organization_id,id));
CREATE TABLE generated_forms(
 id uuid PRIMARY KEY, organization_id uuid NOT NULL, project_id uuid NOT NULL, dossier_id uuid NOT NULL, owner_user_id uuid NOT NULL, mapping_id uuid NOT NULL REFERENCES form_field_mappings(id), input_version integer NOT NULL, inputs_cipher text NOT NULL, input_hash text NOT NULL CHECK(input_hash~'^[a-f0-9]{64}$'), object_key text NOT NULL UNIQUE, envelope_key_cipher text NOT NULL, sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'), status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','confirmed')), confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, FOREIGN KEY(organization_id,project_id,dossier_id) REFERENCES prep_dossiers(organization_id,project_id,id), FOREIGN KEY(organization_id,owner_user_id) REFERENCES users(organization_id,id));
CREATE INDEX documents_dossier ON documents(organization_id,dossier_id,created_at);
CREATE FUNCTION identity_private.protect_document_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'original documents cannot be hard deleted'; END IF;
 IF (to_jsonb(NEW)-ARRAY['scan_status','scan_details_cipher','scanned_at','deleted_at','version','updated_at','verification_status','retained']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['scan_status','scan_details_cipher','scanned_at','deleted_at','version','updated_at','verification_status','retained']) THEN RAISE EXCEPTION 'document source is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_document_source BEFORE UPDATE OR DELETE ON documents FOR EACH ROW EXECUTE FUNCTION identity_private.protect_document_source();
ALTER TABLE form_field_mappings ENABLE ROW LEVEL SECURITY; ALTER TABLE form_field_mappings FORCE ROW LEVEL SECURITY;
ALTER TABLE document_extractions ENABLE ROW LEVEL SECURITY; ALTER TABLE document_extractions FORCE ROW LEVEL SECURITY;
ALTER TABLE generated_forms ENABLE ROW LEVEL SECURITY; ALTER TABLE generated_forms FORCE ROW LEVEL SECURITY;
GRANT SELECT ON form_field_mappings TO noxh_runtime; GRANT SELECT,INSERT,UPDATE ON document_extractions,generated_forms TO noxh_runtime;
CREATE POLICY mappings_project ON form_field_mappings FOR SELECT TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true));
CREATE POLICY extraction_owner ON document_extractions TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true) AND owner_user_id::text=current_setting('app.user_id',true)) WITH CHECK(organization_id::text=current_setting('app.organization_id',true) AND owner_user_id::text=current_setting('app.user_id',true));
CREATE POLICY generated_owner ON generated_forms TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true) AND owner_user_id::text=current_setting('app.user_id',true)) WITH CHECK(organization_id::text=current_setting('app.organization_id',true) AND owner_user_id::text=current_setting('app.user_id',true));
CREATE FUNCTION identity_private.protect_extraction() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'extraction provenance cannot be deleted'; END IF;
 IF OLD.accepted_at IS NOT NULL OR NEW.accepted_at IS NULL OR NEW.accepted_cipher IS NULL OR (to_jsonb(NEW)-ARRAY['accepted_cipher','accepted_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['accepted_cipher','accepted_at']) THEN RAISE EXCEPTION 'extraction suggestions are immutable and acceptance is single use'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_document_extraction BEFORE UPDATE OR DELETE ON document_extractions FOR EACH ROW EXECUTE FUNCTION identity_private.protect_extraction();
CREATE FUNCTION identity_private.protect_generated_form() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'generated form provenance cannot be deleted'; END IF;
 IF OLD.status<>'draft' OR NEW.status<>'confirmed' OR NEW.confirmed_at IS NULL OR NEW.version<>OLD.version+1 OR (to_jsonb(NEW)-ARRAY['status','confirmed_at','version','object_key','envelope_key_cipher','sha256']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','confirmed_at','version','object_key','envelope_key_cipher','sha256']) THEN RAISE EXCEPTION 'generated form inputs and confirmed artifact are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_generated_form BEFORE UPDATE OR DELETE ON generated_forms FOR EACH ROW EXECUTE FUNCTION identity_private.protect_generated_form();
ALTER TABLE documents ADD UNIQUE(organization_id,dossier_id,id);
ALTER TABLE document_extractions ADD FOREIGN KEY(organization_id,dossier_id,document_id) REFERENCES documents(organization_id,dossier_id,id);
ALTER TABLE form_field_mappings ADD UNIQUE(organization_id,project_id,id);
ALTER TABLE generated_forms ADD FOREIGN KEY(organization_id,project_id,mapping_id) REFERENCES form_field_mappings(organization_id,project_id,id);
